export function Positioned(p: P) {
  const anchor = useContext(StackContext);
  const style: CSSProperties = { position: "absolute" };
  for (const name of ["top", "right", "bottom", "left", "width", "height"] as const) {
    if (typeof p[name] === "number") (style as any)[name] = p[name];
  }
  if (p.left == null && p.right == null) {
    if (anchor.includes("Right") || anchor === "right") style.right = 0;
    else if (anchor.includes("Left") || anchor === "left") style.left = 0;
    else {
      style.left = "50%";
      style.transform = "translateX(-50%)";
    }
  }
  if (p.top == null && p.bottom == null) {
    if (anchor.startsWith("bottom")) style.bottom = 0;
    else if (anchor.startsWith("top")) style.top = 0;
    else {
      style.top = "50%";
      style.transform = (style.transform ?? "") + " translateY(-50%)";
    }
  }
  return (
    <div className="studio-positioned" style={style}>
      {p.child}
    </div>
  );
}

