export function Layer(p: P) {
  const anchor: string = p.anchor || "center";
  const style: CSSProperties = { position: "absolute", padding: px(p.inset) };
  if (anchor.includes("Left") || anchor === "left") style.left = 0;
  if (anchor.includes("Right") || anchor === "right") style.right = 0;
  if (anchor.startsWith("top")) style.top = 0;
  if (anchor.startsWith("bottom")) style.bottom = 0;
  if (["top", "bottom", "center", "topCenter", "bottomCenter"].includes(anchor)) {
    style.left = "50%";
    style.transform = "translateX(-50%)";
  }
  if (["left", "right", "center", "centerLeft", "centerRight"].includes(anchor)) {
    style.top = "50%";
    style.transform = (style.transform ?? "") + " translateY(-50%)";
  }
  return <div style={style}>{p.child}</div>;
}

