export function Animate(p: P) {
  const curves: Record<string, string> = {
    linear: "linear", ease: "ease", easeIn: "cubic-bezier(0.42, 0, 1, 1)", easeOut: "cubic-bezier(0, 0, 0.58, 1)",
    easeInOut: "cubic-bezier(0.42, 0, 0.58, 1)", easeOutBack: "cubic-bezier(0.175, 0.885, 0.32, 1.275)",
  };
  const effect: string = p.effect || "fade";
  const distance = has(p.distance) ? n(p.distance) : 24;
  const from: Record<string, [number, number, number]> = {
    fade: [0, 0, 1], slideUp: [0, distance, 1], slideDown: [0, -distance, 1], slideLeft: [distance, 0, 1],
    slideRight: [-distance, 0, 1], scale: [0, 0, 0.9], pop: [0, 0, 0.6],
  };
  const [dx, dy, scale] = from[effect] ?? from.fade;
  return (
    <div
      className="studio-animate"
      style={
        {
          "--studio-animate-x": dx + "px",
          "--studio-animate-y": dy + "px",
          "--studio-animate-scale": scale,
          animationDuration: (has(p.duration) ? n(p.duration) : 400) + "ms",
          animationDelay: n(p.delay) + "ms",
          animationTimingFunction: curves[p.curve] ?? curves.easeOut,
        } as CSSProperties
      }
    >
      {p.child}
    </div>
  );
}

